/* ===== CSS Reset & Variables ===== */
:root {
    --bg-color: #F4F7F6;
    --sidebar-bg: #F9FAFB;
    --white: #FFFFFF;
    --text-main: #333333;
    --text-muted: #888888;
    --primary-color: #38A169; /* Soft green from screenshot */
    --primary-light: #E6F4EA;
    --border-color: #E2E8F0;
    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --font-serif: 'Noto Serif SC', serif;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: var(--font-sans);
    color: var(--text-main);
    background-color: var(--bg-color);
    height: 100vh;
    overflow: hidden;
}

button { cursor: pointer; font-family: inherit; }
input, textarea { font-family: inherit; outline: none; }

.hidden { display: none !important; }

/* ===== Authentication Overlay (Password) ===== */
#auth-overlay {
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    background: rgba(244, 247, 246, 0.8);
    backdrop-filter: blur(10px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}
#auth-overlay.active {
    opacity: 1;
    pointer-events: auto;
}

.auth-box {
    background: var(--white);
    padding: 40px;
    border-radius: 16px;
    box-shadow: var(--shadow-lg);
    width: 400px;
    text-align: center;
}
.auth-box h2 { font-size: 24px; margin-bottom: 10px; font-weight: 600; }
.auth-box p { font-size: 14px; color: var(--text-muted); margin-bottom: 25px; line-height: 1.5; }
.auth-box input {
    width: 100%;
    padding: 12px 16px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    margin-bottom: 20px;
    font-size: 14px;
    transition: border-color 0.2s;
}
.auth-box input:focus { border-color: var(--primary-color); }
.auth-box button {
    width: 100%;
    padding: 12px;
    background: var(--primary-color);
    color: var(--white);
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 500;
    transition: background 0.2s;
}
.auth-box button:hover { background: #2F855A; }
.error-msg { color: #E53E3E; font-size: 13px; margin-top: 10px; min-height: 20px; }

/* ===== Main App Layout ===== */
#app {
    display: flex;
    height: 100vh;
    width: 100vw;
}

/* --- Left Sidebar --- */
.sidebar-left {
    width: 240px;
    background: var(--sidebar-bg);
    border-right: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
}

.sidebar-tabs {
    display: flex;
    padding: 15px 20px 5px;
    gap: 15px;
}
.sidebar-tabs button {
    background: none; border: none; font-size: 13px; color: var(--text-muted);
    padding-bottom: 5px; font-weight: 500;
}
.sidebar-tabs button.active {
    color: var(--text-main); border-bottom: 2px solid var(--primary-color);
}

.sidebar-actions {
    padding: 15px 20px;
}
.btn-secondary {
