.stats-section .stat-item {
    display: flex; justify-content: space-between; padding: 10px 0;
    border-bottom: 1px solid var(--border-color);
    font-size: 13px;
}
.stats-section .stat-item:last-child { border-bottom: none; }
.stat-item .label { color: var(--text-muted); }
.stat-item .value { font-weight: 600; }

/* Toast */
.toast {
    position: fixed; top: 20px; left: 50%; transform: translateX(-50%) translateY(-20px);
    background: var(--text-main); color: var(--white);
    padding: 10px 20px; border-radius: 8px;
    font-size: 14px; opacity: 0; pointer-events: none;
    transition: all 0.3s ease; z-index: 10000;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.success { background: var(--primary-color); }
.toast.error { background: #E53E3E; }
